"use client"

import { useEffect, useRef, useState } from "react"

export type RoomPerson = { id: string; name: string; avatar?: string; role?: string; muted?: boolean }

export type LiveVoiceRoomProps = {
  title?: string
  topic?: string
  speakers: RoomPerson[]
  listeners?: RoomPerson[]
  /** Total audience shown in the header (defaults to everyone listed). */
  audience?: number
  /** Live captions, cycled in order. Each line belongs to a speaker id. */
  captions?: { by: string; text: string }[]
  /** Your seat. You start in the audience, muted. */
  you?: RoomPerson
  /**
   * Per-speaker voice level 0..1, called every frame. Omitted, speech is simulated
   * from the captions so the active speaker's rings move.
   */
  getLevel?: (id: string, t: number) => number
  onLeave?: () => void
  className?: string
}

const FONT =
  "@font-face{font-family:LvrDisplay;src:url(data:font/woff2;base64,) format('woff2');font-weight:600;font-display:swap}" +
  "@font-face{font-family:LvrSans;src:url(data:font/woff2;base64,) format('woff2');font-weight:400 600;font-display:swap}"

