  ".lvr-role{font-size:11px;font-weight:500;color:var(--lvr-amber)}" +
  ".lvr-bars{display:inline-flex;align-items:flex-end;gap:2px;height:10px}" +
  ".lvr-bars i{width:2px;height:10px;border-radius:2px;background:var(--lvr-amber);transform-origin:bottom;transform:scaleY(calc(.2 + var(--lvr-l) * var(--lvr-k)))}" +
  ".lvr-cap{position:relative;display:flex;gap:10px;align-items:flex-start;min-height:62px;padding:12px 14px;border-radius:18px;background:rgba(255,230,200,.05);box-shadow:0 0 0 1px var(--lvr-line) inset;margin-bottom:16px}" +
  ".lvr-cap img{width:26px;height:26px;max-width:none;border-radius:50%;object-fit:cover;flex:none}" +
  ".lvr-cap p{margin:0;font-size:13.5px;line-height:1.45;color:var(--lvr-text)}" +
  ".lvr-cap p b{display:block;font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--lvr-dim);margin-bottom:2px}" +
  ".lvr-cap p span{animation:lvr-word .35s ease both}" +
  ".lvr-aud{display:flex;align-items:center;gap:12px;margin-bottom:18px}" +
  ".lvr-faces{display:flex}" +
  ".lvr-faces>*{width:32px;height:32px;max-width:none;border-radius:50%;object-fit:cover;margin-left:-9px;box-shadow:0 0 0 2.5px var(--lvr-bg);animation:lvr-in .6s cubic-bezier(.34,1.5,.64,1) both;animation-delay:calc(500ms + var(--lvr-i,0) * 60ms)}" +
  ".lvr-faces>*:first-child{margin-left:0}" +
  ".lvr-me{position:relative;display:grid;place-items:center;font-size:12px;font-weight:600;color:#3a2000;background:var(--lvr-amber);transition:box-shadow .3s}" +
  ".lvr-faces>.lvr-me[data-live=true]{box-shadow:0 0 0 2.5px var(--lvr-bg),0 0 0 4.5px var(--lvr-sage)}" +
  ".lvr-aud small{font-size:12.5px;color:var(--lvr-dim)}" +
  ".lvr-aud small b{color:var(--lvr-text);font-weight:600}" +
  ".lvr-bar{display:flex;align-items:center;gap:8px;padding:8px;border-radius:22px;background:rgba(0,0,0,.25);box-shadow:0 0 0 1px var(--lvr-line) inset}" +
  ".lvr-btn{position:relative;height:46px;min-width:46px;padding:0 14px;border:0;border-radius:15px;display:inline-flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;font:600 13.5px LvrSans,ui-sans-serif,system-ui,sans-serif;color:var(--lvr-text);background:#2a211b;" +
  "box-shadow:0 1px 0 rgba(255,240,220,.08) inset,0 0 0 1px var(--lvr-line);transition:transform .25s cubic-bezier(.34,1.56,.64,1),background .2s,color .2s}" +
  ".lvr-btn:hover{background:#352a22}" +
  ".lvr-btn:active{transform:scale(.92)}" +
  ".lvr-btn:focus-visible{outline:2px solid var(--lvr-amber);outline-offset:2px}" +
  ".lvr-btn[aria-pressed=true]{background:var(--lvr-amber);color:#2b1700}" +
  ".lvr-btn[data-kind=mic][aria-pressed=false]{color:var(--lvr-rose)}" +
  ".lvr-btn[data-kind=mic][aria-pressed=true]{background:linear-gradient(180deg,#ffc27a,var(--lvr-amber));box-shadow:0 8px 18px -8px rgba(255,170,80,.8)}" +
  ".lvr-sp-flex{flex:1}" +
  ".lvr-btn{white-space:nowrap}" +
  "@container (max-width:440px){.lvr-lbl{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}.lvr-btn{padding:0 12px}}" +
  ".lvr-leave{background:transparent;color:var(--lvr-rose);box-shadow:0 0 0 1px rgba(255,93,115,.35) inset}" +
  ".lvr-leave:hover{background:rgba(255,93,115,.12)}" +
  ".lvr-reacts{position:absolute;left:50%;bottom:calc(100% + 10px);translate:-50% 0;display:flex;gap:4px;padding:6px;border-radius:18px;background:#2a211b;box-shadow:0 0 0 1px var(--lvr-line),0 18px 30px -12px rgba(0,0,0,.7);animation:lvr-pop .3s cubic-bezier(.34,1.5,.64,1) both;z-index:5}" +
  ".lvr-reacts button{width:40px;height:40px;border:0;border-radius:12px;background:transparent;cursor:pointer;font-size:21px;line-height:1;transition:transform .2s cubic-bezier(.34,1.8,.64,1),background .2s}" +
  ".lvr-reacts button:hover{background:rgba(255,230,200,.08);transform:scale(1.18) translateY(-2px)}" +
  ".lvr-reacts button:focus-visible{outline:2px solid var(--lvr-amber)}" +
  ".lvr-float{position:absolute;bottom:90px;font-size:26px;pointer-events:none;z-index:6;animation:lvr-float 2.4s cubic-bezier(.2,.6,.3,1) forwards}" +
  ".lvr-left{display:flex;flex-direction:column;align-items:center;gap:10px;padding:40px 0 30px;text-align:center;animation:lvr-in .6s both}" +
  ".lvr-left p{margin:0;color:var(--lvr-dim);font-size:13.5px}" +
  ".lvr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}" +
  "@keyframes lvr-rise{from{opacity:0;transform:translateY(20px) scale(.98)}to{opacity:1;transform:none}}" +
  "@keyframes lvr-glow{to{opacity:.6;transform:scale(1.15)}}" +
  "@keyframes lvr-blink{50%{opacity:.3}}" +
  "@keyframes lvr-in{from{opacity:0;transform:translateY(10px) scale(.85)}to{opacity:1;transform:none}}" +
  "@keyframes lvr-pop{from{opacity:0;transform:translateY(6px) scale(.9)}to{opacity:1;transform:none}}" +
  "@keyframes lvr-wave{25%{transform:rotate(-14deg)}75%{transform:rotate(14deg)}}" +
  "@keyframes lvr-word{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}" +
  "@keyframes lvr-float{0%{opacity:0;transform:translate(0,0) scale(.6)}15%{opacity:1;transform:translate(calc(var(--lvr-dx) * .2),-30px) scale(1.15)}100%{opacity:0;transform:translate(var(--lvr-dx),-260px) scale(.9) rotate(var(--lvr-rot))}}" +
  "@media (prefers-reduced-motion:reduce){.lvr-root,.lvr-root::before,.lvr-live i,.lvr-sp,.lvr-faces>*,.lvr-badge,.lvr-cap p span,.lvr-reacts,.lvr-left{animation:none!important}.lvr-float{animation-duration:.01ms!important}.lvr-btn,.lvr-reacts button{transition:none}}"

// #region voice
/** A believable speech envelope: syllable-rate wobble on top of phrase-rate swells, with pauses. */
export function speechLevel(t: number, seed: number) {
  const phrase = 0.5 + 0.5 * Math.sin(t * 1.7 + seed * 3.1)
  const syll = 0.5 + 0.5 * Math.sin(t * 11.3 + seed) * Math.sin(t * 7.1 + seed * 2.3)
  const gap = Math.sin(t * 0.9 + seed * 5) > 0.82 ? 0.15 : 1
  return Math.max(0, Math.min(1, (0.25 + 0.75 * phrase) * (0.35 + 0.65 * syll) * gap))
}

/** Ease a meter towards its target: quick attack, slow release, as audio meters do. */
export function smoothLevel(prev: number, next: number, dt: number) {
  const k = next > prev ? 1 - Math.exp(-dt * 28) : 1 - Math.exp(-dt * 7)
  return prev + (next - prev) * k
}

export function formatElapsed(sec: number) {
  const s = Math.max(0, Math.floor(sec))
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const ss = String(s % 60).padStart(2, "0")
  return h ? h + ":" + String(m).padStart(2, "0") + ":" + ss : m + ":" + ss
}

export function compact(n: number) {
  return n >= 10000 ? Math.round(n / 1000) + "k" : n >= 1000 ? (n / 1000).toFixed(1).replace(/\.0$/, "") + "k" : String(n)
}
// #endregion

const REACTIONS = ["👏", "🔥", "❤️", "😂", "💯"]

const Mic = ({ off }: { off?: boolean }) => (
  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
    <rect x="6.5" y="2.5" width="5" height="8.5" rx="2.5" stroke="currentColor" strokeWidth="1.6" />
    <path d="M4 8.5a5 5 0 0 0 10 0M9 13.5v2.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
    {off && <path d="M3 3l12 12" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" />}
  </svg>
)

const Face = ({ p, size }: { p: RoomPerson; size: number }) =>
  p.avatar ? (
    <img src={p.avatar} alt="" width={size} height={size} />
  ) : (
    <span className="lvr-ini">{p.name.slice(0, 1)}</span>
  )

export default function LiveVoiceRoom({
  title = "Late-night design crit",
  topic = "Bring a work in progress. Five minutes each, kind but honest.",
  speakers,
  listeners = [],
  audience,
  captions = [],
  you = { id: "you", name: "You" },
  getLevel,
  onLeave,
  className = "",
}: LiveVoiceRoomProps) {
  const [cap, setCap] = useState(0)
  const [words, setWords] = useState(0)
  const [muted, setMuted] = useState(true)
  const [hand, setHand] = useState(false)
  const [picker, setPicker] = useState(false)
  const [floats, setFloats] = useState([] as { id: number; e: string; x: number; dx: number; rot: number }[])
  const [elapsed, setElapsed] = useState(1384)
  const [left, setLeft] = useState(false)
  const [say, setSay] = useState("")
  const seats = useRef({} as Record<string, HTMLElement | null>)
  const levels = useRef({} as Record<string, number>)
  const talkRef = useRef("")
  const level = useRef(getLevel)
  level.current = getLevel
  const fid = useRef(0)

  const line = captions[cap % Math.max(1, captions.length)]
  const talker = line?.by || ""
  talkRef.current = talker
  const lineWords = line ? line.text.split(" ") : []

  // Captions type out word by word, hold, then pass to the next line.
  useEffect(() => {
    if (!captions.length || left) return
    if (words < lineWords.length) {
      const t = setTimeout(() => setWords((w) => w + 1), 170 + Math.random() * 120)
      return () => clearTimeout(t)
    }
    const t = setTimeout(() => {
      setCap((c) => c + 1)
      setWords(0)
    }, 1800)
    return () => clearTimeout(t)
  }, [words, lineWords.length, captions.length, left])

  useEffect(() => {
    if (left) return
    const t = setInterval(() => setElapsed((e) => e + 1), 1000)
    return () => clearInterval(t)
  }, [left])

  // Voice meters: one loop writes a CSS variable per seat. It reads nothing from layout.
  useEffect(() => {
    if (left) return
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")
    let raf = 0
    let last = 0
    const ids = speakers.map((s) => s.id).concat(you.id)
    const seed = (id: string) => [...id].reduce((a, c) => a + c.charCodeAt(0), 0) % 17
    const frame = (now: number) => {
      raf = requestAnimationFrame(frame)
      const dt = Math.min(0.05, last ? (now - last) / 1000 : 0.016)
      last = now
      const t = now / 1000
      for (const id of ids) {
        const sp = speakers.find((s) => s.id === id)
        const isMe = id === you.id
        const silent = isMe ? muted : sp?.muted
        let target = 0
        if (!silent) {
          if (level.current) target = level.current(id, t)
          else if (isMe) target = 0
          else if (id === talkRef.current) target = speechLevel(t, seed(id))
        }
        if (reduced.matches) target = target > 0.05 ? 0.4 : 0
        const v = smoothLevel(levels.current[id] || 0, target, dt)
        levels.current[id] = v
        seats.current[id]?.style.setProperty("--lvr-l", v.toFixed(3))
      }
    }
    raf = requestAnimationFrame(frame)
    return () => cancelAnimationFrame(raf)
  }, [speakers, you.id, muted, left])

  const react = (e: string) => {
    setPicker(false)
    const id = ++fid.current
    setFloats((f) => [...f.slice(-14), { id, e, x: 30 + Math.random() * 40, dx: (Math.random() - 0.5) * 120, rot: (Math.random() - 0.5) * 40 }])
    setTimeout(() => setFloats((f) => f.filter((x) => x.id !== id)), 2500)
    setSay("You reacted " + e)
  }

  const crowd = audience ?? speakers.length + listeners.length + 1
  const speaker = speakers.find((s) => s.id === talker)

  if (left)
    return (
      <section className={"lvr-root " + className} aria-label={title}>
        <style>{CSS}</style>
        <div className="lvr-left">
          <h3 className="lvr-h">You left quietly</h3>
          <p>{title} is still live with {compact(crowd - 1)} people.</p>
          <button type="button" className="lvr-btn" style={{ marginTop: 8 }} onClick={() => setLeft(false)}>
            Rejoin room
          </button>
        </div>
      </section>
    )

  return (
    <section className={"lvr-root " + className} aria-label={title}>
      <style>{CSS}</style>
      <div className="lvr-head">
        <span className="lvr-live">
          <i aria-hidden="true" />
          LIVE
        </span>
        <span className="lvr-meta">
          <span aria-label={crowd + " people in the room"}>
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <circle cx="6" cy="5.5" r="2.5" stroke="currentColor" strokeWidth="1.4" />
              <path d="M1.5 13.5c.6-2.3 2.3-3.5 4.5-3.5s3.9 1.2 4.5 3.5M11 3.2a2.5 2.5 0 0 1 0 4.6M12.5 10.3c1 .5 1.7 1.6 2 3.2" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
            </svg>
            {compact(crowd)}
          </span>
          <span aria-label={"Live for " + formatElapsed(elapsed)}>{formatElapsed(elapsed)}</span>
        </span>
      </div>
      <h3 className="lvr-h">{title}</h3>
      <p className="lvr-topic">{topic}</p>

      <ul className="lvr-stage" aria-label="Speakers">
        {speakers.map((s, i) => {
          const talking = s.id === talker && !s.muted
          return (
            <li key={s.id} className="lvr-sp" data-talk={talking} style={{ ["--lvr-i" as string]: i }}>
              <span className="lvr-av" ref={(el) => (seats.current[s.id] = el)}>
                <span className="lvr-ring" aria-hidden="true" />
                <span className="lvr-ring" aria-hidden="true" />
                <Face p={s} size={84} />
                {s.muted && (
                  <span className="lvr-badge" data-tone="muted" aria-hidden="true">
                    <svg width="13" height="13" viewBox="0 0 18 18" fill="none">
                      <rect x="6.5" y="2.5" width="5" height="8.5" rx="2.5" stroke="currentColor" strokeWidth="2" />
                      <path d="M3 3l12 12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                    </svg>
                  </span>
                )}
              </span>
              <span className="lvr-name">
                {talking && (
                  <span className="lvr-bars" aria-hidden="true">
                    {[0.6, 1, 0.75].map((k, j) => (
                      <i key={j} style={{ ["--lvr-k" as string]: k }} />
                    ))}
                  </span>
                )}
                {s.name}
              </span>
              <span className="lvr-role">
                {s.role || " "}
                <span className="lvr-sr">{(talking ? ", speaking" : "") + (s.muted ? ", muted" : "")}</span>
              </span>
            </li>
          )
        })}
      </ul>

      {line && (
        <div className="lvr-cap" aria-live="off">
          {speaker?.avatar && <img src={speaker.avatar} alt="" width={26} height={26} />}
          <p>
            <b>{speaker?.name || "Speaker"} · live captions</b>
            {lineWords.slice(0, words).map((w, i) => (
              <span key={cap + "-" + i}>{w + " "}</span>
            ))}
          </p>
        </div>
      )}

      <div className="lvr-aud">
        <span className="lvr-faces" aria-hidden="true">
          {listeners.slice(0, 5).map((p, i) => (
            <Face key={p.id} p={p} size={32} />
          ))}
          <span className="lvr-me" data-live={!muted} ref={(el) => (seats.current[you.id] = el)} title="You">
            {hand ? "✋" : you.name.slice(0, 1)}
          </span>
        </span>
        <small>
          <b>{compact(Math.max(0, crowd - speakers.length))}</b> listening{hand ? " · your hand is up" : ""}
        </small>
      </div>

      <div className="lvr-bar">
        <button
          type="button"
          className="lvr-btn"
          data-kind="mic"
          aria-pressed={!muted}
          aria-label={muted ? "Unmute microphone" : "Mute microphone"}
          onClick={() => {
            setMuted((m) => !m)
            setSay(muted ? "Microphone on" : "Microphone muted")
          }}
        >
          <Mic off={muted} />
        </button>
        <button
          type="button"
          className="lvr-btn"
          aria-pressed={hand}
          onClick={() => {
            setHand((h) => !h)
            setSay(hand ? "Hand lowered" : "Hand raised. The host will see it.")
          }}
        >
          <svg width="17" height="17" viewBox="0 0 18 18" fill="none" aria-hidden="true">
            <path d="M6 9V3.75a1.25 1.25 0 0 1 2.5 0V8M8.5 7.5V2.75a1.25 1.25 0 0 1 2.5 0V8M11 7.75V4a1.25 1.25 0 0 1 2.5 0v6.5a5.5 5.5 0 0 1-9.6 3.7L2.2 12.1a1.3 1.3 0 0 1 1.9-1.8L6 12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <span className="lvr-lbl">{hand ? "Hand up" : "Raise hand"}</span>
        </button>
        <span style={{ position: "relative" }}>
          <button
            type="button"
            className="lvr-btn"
            aria-label="React"
            aria-expanded={picker}
            aria-haspopup="true"
            onClick={() => setPicker((p) => !p)}
            onKeyDown={(e) => e.key === "Escape" && setPicker(false)}
          >
            <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
              <circle cx="9" cy="9" r="6.75" stroke="currentColor" strokeWidth="1.5" />
              <path d="M6.2 10.5c.6 1 1.6 1.6 2.8 1.6s2.2-.6 2.8-1.6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
              <circle cx="6.8" cy="7.2" r=".9" fill="currentColor" />
              <circle cx="11.2" cy="7.2" r=".9" fill="currentColor" />
            </svg>
          </button>
          {picker && (
            <span className="lvr-reacts" role="group" aria-label="Reactions" onKeyDown={(e) => e.key === "Escape" && setPicker(false)}>
              {REACTIONS.map((r) => (
                <button key={r} type="button" onClick={() => react(r)} aria-label={"React " + r} autoFocus={r === REACTIONS[0]}>
                  {r}
                </button>
              ))}
            </span>
          )}
        </span>
        <span className="lvr-sp-flex" />
        <button
          type="button"
          className="lvr-btn lvr-leave"
          onClick={() => {
            setLeft(true)
            onLeave?.()
          }}
        >
          <span>
            Leave<span className="lvr-lbl"> quietly</span>
          </span>
        </button>
      </div>

      {floats.map((f) => (
        <span key={f.id} className="lvr-float" aria-hidden="true" style={{ left: f.x + "%", ["--lvr-dx" as string]: f.dx + "px", ["--lvr-rot" as string]: f.rot + "deg" }}>
          {f.e}
        </span>
      ))}
      <span className="lvr-sr" aria-live="polite">
        {say}
      </span>
    </section>
  )
}
